import React from "react";
import { Edit2, Trash2, Briefcase } from "lucide-react";

function JobTable({ jobs, onEdit, onDelete }) {
  // Function to format the posted date
  const formatPostedDate = (dateString) => {
    if (!dateString) return "NA";

    const date = new Date(dateString);
    const now = new Date();
    const diffTime = Math.abs(now - date);
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 0) return "Today";
    if (diffDays === 1) return "Yesterday";
    if (diffDays < 7) return `${diffDays} days ago`;
    if (diffDays < 30) return `${Math.floor(diffDays / 7)} weeks ago`;

    // Otherwise show the actual date
    return date.toLocaleDateString('en-US', { 
      year: 'numeric', 
      month: 'short', 
      day: 'numeric' 
    });
  };

  const styles = {
    container: { 
      background: "#fff", 
      borderRadius: "12px", 
      boxShadow: "0 3px 15px rgba(0,0,0,0.05)", 
      overflowX: "auto", 
      padding: "25px" 
    },
    table: { 
      width: "100%", 
      borderCollapse: "collapse" 
    },
    th: { 
      textAlign: "left", 
      fontSize: "13px", 
      fontWeight: 600, 
      padding: "12px 16px", 
      color: "#475569", 
      textTransform: "uppercase" 
    },
    td: { 
      padding: "14px 16px", 
      fontSize: "14px", 
      color: "#334155", 
      borderTop: "1px solid #e2e8f0", 
      verticalAlign: "middle" 
    },
    badge: { 
      display: "inline-block", 
      padding: "4px 12px", 
      fontSize: "12px", 
      fontWeight: 500, 
      borderRadius: "9999px", 
      backgroundColor: "#DBEAFE", 
      color: "#1E40AF" 
    },
    actions: { 
      display: "flex", 
      gap: "10px" 
    },
    btnEdit: { 
      background: "#3b82f6", 
      color: "#fff", 
      border: "none", 
      padding: "6px 10px", 
      borderRadius: "6px", 
      cursor: "pointer",
      display: "flex",
      alignItems: "center",
      justifyContent: "center"
    },
    btnDelete: { 
      background: "#ef4444", 
      color: "#fff", 
      border: "none", 
      padding: "6px 10px", 
      borderRadius: "6px", 
      cursor: "pointer",
      display: "flex",
      alignItems: "center",
      justifyContent: "center"
    },
    emptyContainer: { 
      padding: "48px", 
      textAlign: "center", 
      background: "#fff", 
      borderRadius: "12px", 
      boxShadow: "0 2px 8px rgba(0,0,0,0.05)" 
    },
    emptyTitle: { 
      fontSize: "1.125rem", 
      fontWeight: "500", 
      color: "#111827", 
      marginBottom: "8px" 
    },
    emptyText: { 
      fontSize: "1rem", 
      color: "#4B5563", 
      marginBottom: "24px" 
    },
  };

  if (jobs.length === 0) {
    return (
      <div style={styles.emptyContainer}>
        <Briefcase size={64} color="#D1D5DB" style={{ marginBottom: "16px" }} />
        <h3 style={styles.emptyTitle}>No jobs posted yet</h3>
        <p style={styles.emptyText}>Get started by adding your first job posting</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <table style={styles.table}>
        <thead>
          <tr>
            {["Job Title", "Role", "Location", "CTC", "Type", "Posted", "Actions"].map((col) => (
              <th key={col} style={styles.th}>{col}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {jobs.map((job) => (
            <tr 
              key={job._id} 
              style={{ 
                transition: "background-color 0.2s"
              }}
              onMouseEnter={(e) => e.currentTarget.style.backgroundColor = "#f8fafc"}
              onMouseLeave={(e) => e.currentTarget.style.backgroundColor = "transparent"}
            >
              <td style={styles.td}>
                <div style={{ fontWeight: "500", color: "#111827" }}>{job.title}</div>
                <div style={{ fontSize: "0.875rem", color: "#6B7280" }}>{job.skillset}</div>
              </td>
              <td style={styles.td}>{job.role}</td>
              <td style={styles.td}>{job.location}</td>
              <td style={styles.td}>{job.ctc}</td>
              <td style={styles.td}>
                <span style={styles.badge}>{job.jobType || "Full-time"}</span>
              </td>
              <td style={{ ...styles.td, color: "#6B7280" }}>
                {formatPostedDate(job.createdAt)}
              </td>
              <td style={styles.td}>
                <div style={styles.actions}>
                  <button 
                    onClick={() => onEdit(job)} 
                    style={styles.btnEdit}
                    title="Edit Job"
                  >
                    <Edit2 size={16} />
                  </button>
                  <button 
                    onClick={() => onDelete(job._id)} 
                    style={styles.btnDelete}
                    title="Delete Job"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default JobTable;
